/*
 * THE BUILT-IN CHECK-IN FORMS (DBU-10). Defined here and nowhere else: addStep, saveStep and
 * shared/Steps from template copy one onto a step, and tools/lib/seed.mjs reads this literal for the
 * demo world. A step keeps its own copy (and a CheckinResponse keeps the copy it answered), so
 * changing a form here never changes a check-in already planned, sent or answered.
 *
 * RULES FOR CHANGING A FORM
 *  - A question's `id` is forever: answers are stored by it, and the 6-week estimate on My creations
 *    reads `hours_per_week`. Reword a label freely; never reuse an id for a different question.
 *  - Types: scale (min..max, minLabel/maxLabel), text, textarea, number (min, max, step, suffix),
 *    radio and checkbox (options: [{value, label}], value forever too). `required: true` must be
 *    answered when the question is shown.
 *  - A condition shows a question only when an earlier answer matches (the Hub's SurveyForm rules):
 *    {field, value} (or a list of values), {field, not}, {field, operator: '>'|'<'|'>='|'<=', value}.
 *    Checkin/Question and answerCheckin both apply them; change both together.
 *  - Labels are English, like the emails: they are content the step carries, not interface words.
 * The literal between the markers is strict JSON (seed.mjs parses it).
 */
const FORMS = /* FORMS */[
  {
    "id": "after-session", "title": "After a session", "minutes": 2,
    "questions": [
      { "id": "useful", "type": "scale", "label": "How useful was the session for your teaching?", "min": 1, "max": 5, "minLabel": "Not useful", "maxLabel": "Very useful", "required": true },
      { "id": "change", "type": "textarea", "label": "One thing you'd change for next time", "required": false }
    ]
  },
  {
    "id": "end-of-programme", "title": "End of programme", "minutes": 2,
    "questions": [
      { "id": "confidence_before", "type": "scale", "label": "Before the programme, how confident were you using AI to prepare lessons?", "min": 1, "max": 5, "minLabel": "Not at all", "maxLabel": "Very", "required": true },
      { "id": "confidence_now", "type": "scale", "label": "And how confident are you now?", "min": 1, "max": 5, "minLabel": "Not at all", "maxLabel": "Very", "required": true },
      { "id": "keep_doing", "type": "textarea", "label": "What will you keep doing after the programme?", "required": true }
    ]
  },
  {
    "id": "six-week-impact", "title": "6-week impact", "minutes": 2,
    "questions": [
      { "id": "still_using", "type": "radio", "label": "Are you still using what you learned?", "required": true,
        "options": [ { "value": "weekly", "label": "Yes, every week" }, { "value": "sometimes", "label": "Now and then" }, { "value": "no", "label": "Not really" } ] },
      { "id": "hours_per_week", "type": "number", "label": "About how many hours a week does it save you?", "hint": "Your own estimate. Half hours are fine.", "min": 0, "max": 40, "step": 0.5, "suffix": "hours a week", "required": true,
        "condition": { "field": "still_using", "value": ["weekly", "sometimes"] } },
      { "id": "in_the_way", "type": "textarea", "label": "What got in the way?", "required": false,
        "condition": { "field": "still_using", "value": "no" } },
      { "id": "story", "type": "textarea", "label": "One story: a lesson or a moment where it made a difference", "required": false,
        "condition": { "field": "still_using", "not": "no" } }
    ]
  }
]/* END FORMS */;
Outputs.forms = JSON.parse(JSON.stringify(FORMS));
Outputs.done();
